package com.example.meetomxh.fragments;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import androidx.annotation.*;
import androidx.recyclerview.widget.LinearLayoutManager;
import com.google.android.material.bottomsheet.BottomSheetDialogFragment;
import com.example.meetomxh.adapters.CommentAdapter;
import com.example.meetomxh.databinding.LayoutCommentsBottomSheetBinding;
import com.example.meetomxh.models.Comment;
import com.example.meetomxh.ui.MentionComposer;
import com.example.meetomxh.supabase.*;
import org.json.*;
import java.util.*;
public class CommentsBottomSheetFragment extends BottomSheetDialogFragment implements CommentAdapter.OnCommentClickListener {
 private static final java.util.Map<String,JSONObject> DRAFTS=new java.util.concurrent.ConcurrentHashMap<>();
 private LayoutCommentsBottomSheetBinding binding;private CommentAdapter adapter;private MentionComposer mentionComposer;private String postId,parent,reply;private Subscription observer;private String afterTime,afterId;private boolean hasMore=true,loadingMore;
 public static CommentsBottomSheetFragment newInstance(String id){CommentsBottomSheetFragment f=new CommentsBottomSheetFragment();Bundle args=new Bundle();args.putString("post",id);f.setArguments(args);return f;}
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater inflater,@Nullable ViewGroup container,@Nullable Bundle state){binding=LayoutCommentsBottomSheetBinding.inflate(inflater,container,false);return binding.getRoot();}
 @Override public void onViewCreated(@NonNull View v,@Nullable Bundle state){postId=requireArguments().getString("post");mentionComposer=new MentionComposer(binding.etCommentInput);String draftKey=draftKey();JSONObject draft=DRAFTS.get(draftKey);if(draft!=null){binding.etCommentInput.setText(draft.optString("body",""));mentionComposer.restore(draft.optJSONArray("mentions"));parent=nullable(draft,"parent");reply=nullable(draft,"reply");}adapter=new CommentAdapter(SessionManager.getInstance().uid(),this);binding.rvComments.setLayoutManager(new LinearLayoutManager(requireContext()));binding.rvComments.setAdapter(adapter);binding.btnCloseComments.setOnClickListener(x->{if(parent!=null){parent=null;reply=null;listen();}else dismiss();});binding.btnSendComment.setOnClickListener(x->send());binding.tvEmptyComments.setOnClickListener(x->{if(adapter.getItemCount()==0)listen();else loadMore();});binding.rvComments.addOnScrollListener(new androidx.recyclerview.widget.RecyclerView.OnScrollListener(){public void onScrolled(androidx.recyclerview.widget.RecyclerView r,int dx,int dy){androidx.recyclerview.widget.LinearLayoutManager lm=(androidx.recyclerview.widget.LinearLayoutManager)r.getLayoutManager();if(dy>0&&lm.findLastVisibleItemPosition()>=adapter.getItemCount()-4)loadMore();}});listen();}
 private void listen(){if(observer!=null)observer.remove();afterTime=null;afterId=null;hasMore=true;loadingMore=false;observer=new com.example.meetomxh.supabase.Observer<>(()->CommentClient.page(postId,parent,null,null,30),new Api.Callback<List<Comment>>(){public void success(List<Comment> rows){if(binding==null)return;List<Comment> merged=new ArrayList<>(rows);if(afterTime!=null){Set<String> ids=new HashSet<>();for(Comment c:merged)ids.add(c.getCommentId());for(Comment c:adapter.getComments())if(ids.add(c.getCommentId()))merged.add(c);merged.sort((a,b)->{int t=Long.compare(b.getCreatedAt(),a.getCreatedAt());return t!=0?t:b.getCommentId().compareTo(a.getCommentId());});}adapter.setComments(merged);hasMore=merged.size()>=30;updateState(merged);}public void error(String e){if(binding!=null){binding.tvEmptyComments.setText(e+" · Chạm để thử lại");binding.tvEmptyComments.setVisibility(View.VISIBLE);}}});}
 private void updateState(List<Comment> rows){if(rows.isEmpty()){binding.tvEmptyComments.setText("Chưa có bình luận. Hãy mở đầu cuộc trò chuyện.");binding.tvEmptyComments.setVisibility(View.VISIBLE);}else{binding.tvEmptyComments.setVisibility(View.GONE);Comment last=rows.get(rows.size()-1);afterTime=last.serverCreatedAt;afterId=last.getCommentId();}}
 private void loadMore(){if(loadingMore||!hasMore||afterTime==null||binding==null)return;loadingMore=true;binding.tvEmptyComments.setText("Đang tải bình luận cũ hơn…");binding.tvEmptyComments.setVisibility(View.VISIBLE);String time=afterTime,id=afterId;Api.run(()->CommentClient.page(postId,parent,time,id,30),new Api.Callback<List<Comment>>(){public void success(List<Comment> rows){if(binding==null)return;loadingMore=false;hasMore=rows.size()==30;adapter.appendComments(rows);if(!rows.isEmpty()){Comment last=rows.get(rows.size()-1);afterTime=last.serverCreatedAt;afterId=last.getCommentId();}binding.tvEmptyComments.setVisibility(View.GONE);}public void error(String e){if(binding!=null){loadingMore=false;binding.tvEmptyComments.setText(e+" · Chạm để thử lại");binding.tvEmptyComments.setVisibility(View.VISIBLE);}}});} private void send(){String text=binding.etCommentInput.getText().toString().trim();if(text.isEmpty())return;binding.btnSendComment.setEnabled(false);JSONObject args=Api.obj("p_post_id",postId,"p_parent_id",reply==null?parent:reply,"p_body",text,"p_mentions",mentionComposer.getMentions());String fingerprint=args.toString();Api.run(()->{args.put("p_client_request_id",RequestIds.get("comment",fingerprint));Object r=RpcClient.call("create_comment_with_mentions",args);RequestIds.complete("comment",fingerprint);return r;},new Api.Callback<Object>(){public void success(Object r){PostUpdates.reconcile(postId);if(binding==null)return;DRAFTS.remove(draftKey());binding.etCommentInput.setText("");binding.btnSendComment.setEnabled(true);if(reply!=null){parent=reply;reply=null;}listen();}public void error(String e){if(binding!=null){binding.btnSendComment.setEnabled(true);toast(e);}}});}
 @Override public void onCommentClick(Comment c){List<String> choices=new ArrayList<>(Arrays.asList("Trả lời","Xem trả lời"));boolean own=SessionManager.getInstance().uid().equals(c.getAuthorUid())&&"published".equals(c.state);if(own){choices.add("Sửa");choices.add("Xóa");}new android.app.AlertDialog.Builder(requireContext()).setItems(choices.toArray(new String[0]),(d,i)->{if(i==0){reply=c.getCommentId();binding.etCommentInput.setHint("Trả lời bình luận");binding.etCommentInput.requestFocus();}else if(i==1){parent=c.getCommentId();reply=null;listen();}else if(i==2){EditText edit=new EditText(requireContext());edit.setText(c.getContent());MentionComposer editor=new MentionComposer(edit);editor.restore(c.mentions);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(requireContext()).setTitle("Sửa bình luận").setView(edit).setPositiveButton("Lưu",null).setNegativeButton("Hủy",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(b->change("change_comment_with_mentions",Api.obj("p_comment_id",c.getCommentId(),"p_body",edit.getText().toString(),"p_expected_version",c.version,"p_mentions",editor.getMentions()))));dialog.setOnDismissListener(x->editor.dispose());dialog.show();}else onDeleteCommentClick(c);}).show();}
 @Override public void onDeleteCommentClick(Comment c){change("delete_comment",Api.obj("p_comment_id",c.getCommentId(),"p_expected_version",c.version));}
 @Override public void onCommentReaction(Comment c,String reaction,com.example.meetomxh.adapters.FeedAdapter.ReactionCallback cb){Api.run(()->RpcClient.call("set_comment_reaction",Api.obj("p_comment_id",c.getCommentId(),"p_reaction",reaction)),new Api.Callback<Object>(){public void success(Object r){cb.onResult(true,null);}public void error(String e){cb.onResult(false,e);}});}
 private void change(String rpc,JSONObject args){Api.run(()->RpcClient.call(rpc,args),new Api.Callback<Object>(){public void success(Object r){PostUpdates.reconcile(postId);if(binding!=null)listen();}public void error(String e){toast(e);}});}
 private void toast(String e){if(isAdded())Toast.makeText(requireContext(),e,Toast.LENGTH_LONG).show();}
 private String draftKey(){return SessionManager.getInstance().uid()+":"+postId;}
 private static String nullable(JSONObject o,String key){String v=o.optString(key,null);return v==null||v.equals("null")?null:v;}
 @Override public void onDestroyView(){if(binding!=null&&mentionComposer!=null){JSONObject draft=Api.obj("body",binding.etCommentInput.getText().toString(),"mentions",mentionComposer.getMentions(),"parent",parent,"reply",reply);DRAFTS.put(draftKey(),draft);}if(observer!=null)observer.remove();if(mentionComposer!=null)mentionComposer.dispose();binding=null;super.onDestroyView();}
}
